mapper.select:
SELECT ips.target_pool_id AS poolId ,CASE WHEN ips.security_type = 'crmw' THEN 'crmw' WHEN ips.security_type = 'company' THEN 'company' WHEN dst.category_type IS NOT NULL AND dst.category_type != '' THEN dst.category_type ELSE 'unknown' END AS typeCode ,COUNT(DISTINCT ips.security_code) AS count FROM ip_pool_status ips LEFT JOIN dict_security_type dst ON dst.security_type = ips.security_type AND dst.is_deleted = 0 WHERE ips.audit_status = '20' AND ips.is_deleted = 0 AND ips.target_pool_id IN
#{poolId}
GROUP BY ips.target_pool_id ,CASE WHEN ips.security_type = 'crmw' THEN 'crmw' WHEN ips.security_type = 'company' THEN 'company' WHEN dst.category_type IS NOT NULL AND dst.category_type != '' THEN dst.category_type ELSE 'unknown' END

SELECT si.wind_code AS securityCode ,si.short_name AS securityShortName ,si.security_type ,CONCAT_WS(',' ,IF(si.wind_code_sh IS NOT NULL AND si.wind_code_sh != '', 'SSE', NULL) ,IF(si.wind_code_sz IS NOT NULL AND si.wind_code_sz != '', 'SZSE', NULL) ,IF(si.wind_code_nib IS NOT NULL AND si.wind_code_nib != '', 'CIBM', NULL) ,IF(si.wind_code_bj IS NOT NULL AND si.wind_code_bj != '', 'BSE', NULL) ,IF(si.wind_code_nbc IS NOT NULL AND si.wind_code_nbc != '', 'OTHER', NULL) ) AS marketCodeText ,si.issuer ,si.rating_bond ,si.rating_bondissuer ,si.inner_issuer_rating ,si.maturity_date ,si.date_exists ,si.guarantor ,si.guarantor_id FROM rrs_securityinfo si
AND si.security_type NOT IN ('crmw', 'company') AND si.security_status != 'D'
AND NOT EXISTS ( SELECT 1 FROM ip_pool_status ips WHERE ips.security_code = si.wind_code AND ips.target_pool_id = #{poolId} AND ips.audit_status = '20' AND ips.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM ip_pool_status ips WHERE ips.security_code = si.wind_code AND ips.target_pool_id = #{poolId} AND ips.audit_status = '20' AND ips.is_deleted = 0 )
AND (
OR EXISTS ( SELECT 1 FROM ip_pool_status src WHERE src.security_code = si.wind_code AND src.audit_status = '20' AND src.is_deleted = 0 AND src.target_pool_id IN
#{srcPoolId}
)
OR EXISTS ( SELECT 1 FROM ip_pool_status_crmw src WHERE src.audit_status = '20' AND src.is_deleted = 0 AND (src.security_code = si.wind_code OR src.crmw_scode = si.wind_code) AND src.target_pool_id IN
#{srcPoolId}
)
)
AND si.wind_code LIKE CONCAT('%', #{securityCode}, '%')
AND si.short_name LIKE CONCAT('%', #{securityShortName}, '%')
AND ( si.issuer LIKE CONCAT('%', #{issuer}, '%') OR si.issuer_code LIKE CONCAT('%', #{issuer}, '%') )
AND (
si.wind_code_sh IS NOT NULL AND si.wind_code_sh != '' si.wind_code_sz IS NOT NULL AND si.wind_code_sz != '' si.wind_code_nib IS NOT NULL AND si.wind_code_nib != '' si.wind_code_bj IS NOT NULL AND si.wind_code_bj != '' si.wind_code_nbc IS NOT NULL AND si.wind_code_nbc != '' si.security_type = 'company' 1 = 0
)
